section('inventory: exclusive and capacity conflicts');
$cB = $comp('Beta Labs', 'https://beta-labs.example'); $cC = $comp('Gamma AI', 'https://gamma.example'); $cD = $comp('Delta ML', 'https://delta.example'); $cE = $comp('Epsilon AI', 'https://epsilon.example');
$mk = function (int $cid, int $pkg, string $tool, string $category, string $s, string $e) use ($pdo, $owner) { [$k, $id] = ad_booking_create($pdo, $owner, $cid, ['package_id' => (string)$pkg, 'tool_slug' => $tool, 'category' => $category, 'agreed_price' => '10.00', 'currency' => 'USD', 'start_date' => $s, 'end_date' => $e]); return (int)$id; };
$approve = function (int $bid) use ($pdo, $owner) { $b = ad_booking_get($pdo, $bid); crm_campaign_update($pdo, $owner, (int)$b['campaign_id'], ['disclosure_label' => 'Sponsored', 'landing_url' => 'https://x.example/a']); crm_campaign_move($pdo, $owner, (int)$b['campaign_id'], 'in_review'); crm_campaign_move($pdo, $owner, (int)$b['campaign_id'], 'approved'); };
$toAwait = function (int $bid) use ($pdo, $owner, $N, $approve) { $approve($bid); ad_booking_move($pdo, $owner, $bid, 'enquiry_received', '', $N); ad_booking_move($pdo, $owner, $bid, 'proposal_sent', '', $N); return ad_booking_move($pdo, $owner, $bid, 'awaiting_payment', '', $N); };
$f2 = $mk($cB, $pidF, $T2, '', $d(5), $d(25)); $f3 = $mk($cC, $pidF, $T3, '', $d(6), $d(26)); $f4 = $mk($cD, $pidF, $T4, '', $d(7), $d(27)); $f5 = $mk($cE, $pidF, $T5, '', $d(8), $d(28));
ok($toAwait($f2)[0] && $toAwait($f3)[0], 'two more featured bookings reserve slots (capacity 3 with the first)'); ok($toAwait($f4)[1] === 'booking_conflict', 'the fourth overlapping Featured Tool booking is refused (capacity 3 reached)'); $f5b = $mk($cE, $pidF, $T5, '', $d(40), $d(60)); ok($toAwait($f5b)[0] === true, 'the same package outside the overlapping dates is fine');
$same1 = $mk($cB, $pidH, $T1, '', $d(10), $d(20)); ok($toAwait($same1)[1] === 'booking_conflict', 'one tool cannot hold two overlapping public placements (featured + spotlight)'); $sp1 = $mk($cB, $pidH, $T2, '', $d(60), $d(90)); $sp2 = $mk($cC, $pidH, $T3, '', $d(70), $d(95)); ok($toAwait($sp1)[0] === true && $toAwait($sp2)[1] === 'booking_conflict', 'Homepage Spotlight is exclusive: a second overlapping booking is refused');
$cs1 = $mk($cB, $pidC, '', 'Coding', $d(5), $d(35)); $cs2 = $mk($cC, $pidC, '', 'Coding', $d(10), $d(40)); $cs3 = $mk($cC, $pidC, '', 'Writing', $d(10), $d(40)); ok($toAwait($cs1)[0] === true && $toAwait($cs2)[1] === 'booking_conflict' && $toAwait($cs3)[0] === true, 'Category Sponsor is exclusive PER CATEGORY: Coding twice is refused, Writing is fine');
ok(ad_booking_update($pdo, $owner, $cs3, ['package_id' => (string)$pidC, 'category' => 'Coding', 'agreed_price' => '10.00', 'currency' => 'USD', 'start_date' => $d(10), 'end_date' => $d(40)])[1] === 'booking_conflict', 'editing a held booking into a conflict is refused'); $inv = ad_inventory($pdo, $N); $iF = array_values(array_filter($inv, fn($i) => $i['package']['code'] === 'featured_tool'))[0]; ok($iF['capacity'] === 3 && $iF['available'] && $iF['booked_90d'] >= 3, 'inventory shows capacity and bookings'); $iN = array_values(array_filter($inv, fn($i) => $i['package']['code'] === 'newsletter_sponsor'))[0]; ok($iN['available'] === false, 'the newsletter package is reported as not available');
foreach ([$f2, $f3, $f5, $f5b, $same1, $sp1, $sp2, $cs1, $cs2, $cs3, $f4] as $x) { try { ad_booking_move($pdo, $owner, $x, 'cancelled', 'test cleanup', $N); } catch (Throwable $e) {} }

section('agreement and payments through the existing CRM and finance records');
