ok(ad_record_payment($pdo, $sales, $b1, 'invoiced', '49.00', $today, 'INV-1')[1] === 'forbidden', 'only the owner records money'); ok(ad_record_payment($pdo, $owner, $b1, 'invoiced', '49.00', $today, '')[1] === 'reference_required', 'a reference is required'); ok(ad_record_payment($pdo, $owner, $b1, 'invoiced', '49.00', $today, 'INV-1')[0] === true, 'invoice recorded');
ok(ad_record_payment($pdo, $owner, $b1, 'invoiced', '49.00', $today, 'INV-1')[1] === 'duplicate_entry' && (int)$pdo->query("SELECT COUNT(*) FROM crm_revenue_entries WHERE contract_id = " . (int)$cid)->fetchColumn() === 1, 'the same invoice reference cannot be entered twice (no duplicate revenue)'); $P = ad_payment_summary($pdo, ad_booking_get($pdo, $b1)); ok($P['invoiced'] === 4900 && $P['received'] === 0 && $P['outstanding'] === 4900 && $P['state'] === 'awaiting_payment', 'invoiced is not received: state Awaiting payment');
ok(ad_record_payment($pdo, $owner, $b1, 'received', '60.00', $today, 'PAY-0')[1] === 'received_exceeds_invoiced', 'received cannot exceed invoiced (existing rule)'); ok($st($b1, 'scheduled', '', $owner)[1] === 'payment_or_override_required', 'scheduling needs payment, or an owner reason'); ok($st($b1, 'scheduled', '', $sales)[1] === 'forbidden', 'sales cannot schedule');
ok(ad_record_payment($pdo, $owner, $b1, 'received', '20.00', $today, 'PAY-1')[0] === true && ad_payment_summary($pdo, ad_booking_get($pdo, $b1))['state'] === 'partly_paid', 'partial payment: Partly paid'); ok(ad_record_payment($pdo, $owner, $b1, 'received', '29.00', $today, 'PAY-2')[0] === true, 'rest received'); $P = ad_payment_summary($pdo, ad_booking_get($pdo, $b1)); ok($P['received'] === 4900 && $P['state'] === 'paid' && $P['outstanding'] === 0, 'Paid');
$pdo->prepare("INSERT INTO fin_adjustment (contract_id, kind, amount_minor, currency, entry_date, reference, note, created_by, created_at) VALUES (?, 'refund', 1000, 'USD', ?, 'RF-1', 'partial', ?, ?)")->execute([(int)$cid, $today, (int)$o1, crm_now()]); $P = ad_payment_summary($pdo, ad_booking_get($pdo, $b1)); ok($P['refunds'] === 1000 && $P['net_received'] === 3900 && $P['state'] === 'paid', 'a refund recorded in Finance reduces net received');
